def choose_move(observation):
    # Defensive defaults
    x = observation.get("player_x", 0)
    y = observation.get("player_y", 0)

    # Attempt to infer simple goals from available fields
    # Resource collection: look for nearest resource
    resources = observation.get("resources", [])
    # Pursuit-evasion: look for nearest evader or pursuer
    evaders = observation.get("evaders", [])
    allies = observation.get("allies", [])
    # Territory control: look for nearest opponent base or territory markers
    enemies = observation.get("enemies", [])
    bases = observation.get("bases", [])

    # Default behavior: stay still
    dx = 0
    dy = 0

    # Helper: compute simple Manhattan distance to a target
    def dist(px, py, tx, ty):
        return abs(px - tx) + abs(py - ty)

    # Resource collection heuristic
    best_r = None
    best_r_d = 0
    if isinstance(resources, list) and resources:
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            if rx is None or ry is None:
                continue
            d = dist(x, y, rx, ry)
            if best_r is None or d < best_r_d:
                best_r = (rx, ry)
                best_r_d = d
        if best_r is not None and best_r_d > 0:
            dx = 0
            dy = 0
            if best_r[0] > x:
                dx = 1
            elif best_r[0] < x:
                dx = -1
            if best_r[1] > y:
                dy = 1
            elif best_r[1] < y:
                dy = -1
            return [dx, dy]

    # Pursuit/Evasion heuristic
    best_e = None
    best_e_d = None
    if isinstance(evaders, list) and evaders:
        for e in evaders:
            ex = e.get("x", 0)
            ey = e.get("y", 0)
            if ex is None or ey is None:
                continue
            d = dist(x, y, ex, ey)
            if best_e_d is None or d < best_e_d:
                best_e = (ex, ey)
                best_e_d = d
    if best_e is not None and best_e_d is not None:
        # Move away from evader if close; otherwise approach least risky direction
        if best_e_d <= 2:
            dx = 0
            dy = 0
            if best_e[0] > x:
                dx = -1
            elif best_e[0] < x:
                dx = 1
            if best_e[1] > y:
                dy = -1
            elif best_e[1] < y:
                dy = 1
            return [dx, dy]

    # Territory control heuristic: approach nearest base/enemy base
    best_b = None
    best_b_d = None
    if isinstance(bases, list) and bases:
        for b in bases:
            bx = b.get("x", 0)
            by = b.get("y", 0)
            if bx is None or by is None:
                continue
            d = dist(x, y, bx, by)
            if best_b_d is None or d < best_b_d:
                best_b = (bx, by)
                best_b_d = d
    if best_b is not None and best_b_d is not None:
        dx = 0
        dy = 0
        if best_b[0] > x:
            dx = 1
        elif best_b[0] < x:
            dx = -1
        if best_b[1] > y:
            dy = 1
        elif best_b[1] < y:
            dy = -1
        return [dx, dy]

    # If no information, stay or make small random-like move via deterministic rule
    # Deterministic: try to move right if possible else down
    return [1, 0]

