        d = abs(rx - x) + abs(ry - y)
        if d < best_d:
            best_d = d
            best_r = (rx, ry)

    if best_r is not None:
        target = best_r
        td = best_d

    if target is None:
        # chase opponent
        target = (ox, oy)
        td = abs(ox - x) + abs(oy - y)

    if target is not None and td > 0:
        tx, ty = target
